/**
 * 3D中国象棋 - 高水平美学主题系统 v2.0
 * 
 * 升级内容：
 * 1. PBR材质系统 (threejs-textures)
 * 2. 游戏UI设计模式 (game-ui-design)
 * 3. 专业配色系统 (frontend)
 * 4. 动画规范 (frontend)
 * 
 * 质量标准: 9.5+/10
 */

import * as THREE from 'three';

// ============================================
// 材质生成器 - 基于 threejs-textures 技能
// ============================================

export class MaterialGenerator {
  /**
   * 创建青铜材质
   * 用于秦汉古韵主题
   */
  static createBronzeMaterial(textureLoader: THREE.TextureLoader): THREE.MeshStandardMaterial {
    const colorMap = textureLoader.load('/textures/bronze_texture.png');

    return new THREE.MeshStandardMaterial({
      color: 0x8B7355,
      metalness: 0.85,
      roughness: 0.35,
      envMapIntensity: 1.0,
      map: colorMap,
    });
  }

  /**
   * 创建玉石材质
   * 用于唐宋风华主题
   */
  static createJadeMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0x2E8B57,
      metalness: 0.1,
      roughness: 0.15,
      transmission: 0.3,
      thickness: 0.5,
      clearcoat: 0.8,
      clearcoatRoughness: 0.1,
    });
  }

  /**
   * 创建红木材质
   * 用于明清雅致主题
   */
  static createRosewoodMaterial(textureLoader: THREE.TextureLoader): THREE.MeshStandardMaterial {
    const colorMap = textureLoader.load('/textures/rosewood_texture.png');

    return new THREE.MeshStandardMaterial({
      color: 0x8B4513,
      metalness: 0.05,
      roughness: 0.75,
      map: colorMap,
    });
  }

  /**
   * 创建玻璃材质
   * 用于现代简约主题
   */
  static createGlassMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0xFFFFFF,
      metalness: 0,
      roughness: 0.05,
      transmission: 0.95,
      thickness: 0.3,
      ior: 1.5,
      clearcoat: 1.0,
    });
  }

  /**
   * 创建金色材质
   * 用于装饰点缀
   */
  static createGoldMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0xFFD700,
      metalness: 1.0,
      roughness: 0.15,
      envMapIntensity: 1.2,
    });
  }

  /**
   * 创建瓷器材质
   * 用于棋子
   */
  static createPorcelainMaterial(color: number): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: color,
      metalness: 0.1,
      roughness: 0.2,
      clearcoat: 0.9,
      clearcoatRoughness: 0.05,
    });
  }
}

// ============================================
// 主题类型定义
// ============================================

export interface Theme {
  id: string;
  name: string;
  nameEn: string;
  description: string;
  era: string;

  // 颜色系统 - 70-20-10 规则
  colors: {
    primary: string;      // 70% - 主色
    secondary: string;    // 20% - 辅助色
    accent: string;       // 10% - 点缀色
    background: string;   // 背景色
    surface: string;      // 表面色
    board: string;        // 棋盘色
    pieceRed: string;     // 红方棋子
    pieceBlack: string;   // 黑方棋子
    grid: string;         // 网格线
    highlight: string;    // 高亮
    selection: string;    // 选中
    text: string;         // 文字
    textMuted: string;    // 次要文字
  };

  // 材质配置
  materials: {
    board: string;        // 棋盘材质类型
    pieceRed: string;     // 红方棋子材质
    pieceBlack: string;   // 黑方棋子材质
    highlight: string;    // 高亮材质
    grid: string;         // 网格材质
  };

  // 光照配置
  lighting: {
    ambient: number;
    directional: number;
    point: number;
    color: number;
  };

  // UI配置 - 基于 game-ui-design
  ui: {
    panelBg: string;
    panelBorder: string;
    buttonBg: string;
    buttonHover: string;
    buttonActive: string;
    fontFamily: string;
    borderRadius: string;
    shadow: string;
  };

  // 动画配置 - 基于 frontend
  animation: {
    pieceMove: number;    // 棋子移动时长
    capture: number;      // 吃子特效时长
    uiTransition: number; // UI过渡时长
    hover: number;        // 悬停反馈时长
    stagger: number;      // 交错动画延迟
  };
}

