  name: '现代简约',
  nameEn: 'Modern Minimalist',
  description: '极简设计，水晶玻璃，诠释现代美学的纯粹之美',
  era: 'Modern',

  colors: {
    primary: '#2C3E50',
    secondary: '#ECF0F1',
    accent: '#3498DB',
