// 导出所有主题
// ============================================

export const themes: Record<string, Theme> = {
  qinhan: qinhanTheme,
  tangsong: tangsongTheme,
  mingqing: mingqingTheme,
  modern: modernTheme,
};

export const defaultTheme = mingqingTheme;

// ============================================
// 动画配置 - 基于 frontend 技能
// ============================================

export const animationConfig = {
  // 棋子移动动画
  pieceMove: {
    duration: 0.3,
    ease: [0.4, 0, 0.2, 1], // ease-out
    liftHeight: 0.5,
    scale: 1.1,
  },

  // 吃子特效
  capture: {
    particleCount: 20,
    spread: 2,
    duration: 0.5,
    colors: ['#FFD700', '#FF6B6B', '#FFFFFF'],
  },

  // UI动画
  ui: {
    fast: 0.15,      // 悬停、点击
    normal: 0.3,     // 过渡、展开
    slow: 0.5,       // 页面切换
    stagger: 0.08,   // 交错延迟
  },
};

// ============================================
// 材质创建工厂
// ============================================

export class MaterialFactory {
  private textureLoader: THREE.TextureLoader;

  constructor() {
    this.textureLoader = new THREE.TextureLoader();
  }

  createMaterial(type: string, theme: Theme): THREE.Material {
    switch (type) {
      case 'bronze':
        return MaterialGenerator.createBronzeMaterial(this.textureLoader);
      case 'jade':
        return MaterialGenerator.createJadeMaterial();
      case 'rosewood':
        return MaterialGenerator.createRosewoodMaterial(this.textureLoader);
      case 'glass':
        return MaterialGenerator.createGlassMaterial();
      case 'gold':
        return MaterialGenerator.createGoldMaterial();
      case 'porcelain-rose':
        return MaterialGenerator.createPorcelainMaterial(0xE85D75);
      case 'porcelain-blue':
        return MaterialGenerator.createPorcelainMaterial(0x4A90A4);
      case 'crystal-red':
        return new THREE.MeshPhysicalMaterial({
          color: 0xFF6B6B,
          transmission: 0.6,
          thickness: 0.4,
          roughness: 0.1,
          clearcoat: 1.0,
        });
      case 'crystal-cyan':
        return new THREE.MeshPhysicalMaterial({
          color: 0x4ECDC4,
          transmission: 0.6,
          thickness: 0.4,
          roughness: 0.1,
          clearcoat: 1.0,
        });
      default:
        return new THREE.MeshStandardMaterial({ color: 0x888888 });
    }
  }
}

