        return MaterialGenerator.createGlassMaterial();
      case 'gold':
        return MaterialGenerator.createGoldMaterial();
      case 'porcelain-rose':
        return MaterialGenerator.createPorcelainMaterial(0xE85D75);
      case 'porcelain-blue':
        return MaterialGenerator.createPorcelainMaterial(0x4A90A4);
      case 'crystal-red':
        return new THREE.MeshPhysicalMaterial({
          color: 0xFF6B6B,
          transmission: 0.6,
          thickness: 0.4,
          roughness: 0.1,
          clearcoat: 1.0,
        });
      case 'crystal-cyan':
        return new THREE.MeshPhysicalMaterial({
          color: 0x4ECDC4,
          transmission: 0.6,
          thickness: 0.4,
          roughness: 0.1,
          clearcoat: 1.0,
        });
      default:
        return new THREE.MeshStandardMaterial({ color: 0x888888 });
    }
  }
}
