// 材质生成器
export class MaterialGenerator {
  static createBronzeMaterial(textureLoader: THREE.TextureLoader): THREE.MeshStandardMaterial {
    const colorMap = textureLoader.load('/textures/bronze_texture.png');
    return new THREE.MeshStandardMaterial({
      color: 0x8B7355,
      metalness: 0.85,
      roughness: 0.35,
      envMapIntensity: 1.0,
      map: colorMap,
    });
  }

  static createJadeMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0x2E8B57,
      metalness: 0.1,
      roughness: 0.15,
      transmission: 0.3,
      thickness: 0.5,
      clearcoat: 0.8,
      clearcoatRoughness: 0.1,
