    return new THREE.MeshPhysicalMaterial({
      color: 0xFFFFFF,
      metalness: 0,
      roughness: 0.05,
      transmission: 0.95,
      thickness: 0.3,
      ior: 1.5,
      clearcoat: 1.0,
    });
  }

  static createGoldMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0xFFD700,
      metalness: 1.0,
      roughness: 0.15,
      envMapIntensity: 1.2,
    });
