    shadow: '0 4px 16px rgba(0, 0, 0, 0.4)',
  },
  animation: {
    pieceMove: 350,
    capture: 450,
    uiTransition: 280,
    hover: 180,
    stagger: 120,
  },
};

// 现代简约 - 玻璃主题
export const modernTheme: Theme = {
  id: 'modern',
  name: '现代简约',
  nameEn: 'Modern Minimalist',
  description: '极简设计，水晶玻璃，诠释现代美学的纯粹之美',
  era: 'Modern',
  colors: {
    primary: '#2C3E50',
    secondary: '#ECF0F1',
    accent: '#3498DB',
    background: '#1A1A2E',
    surface: '#16213E',
    board: 'rgba(255,255,255,0.05)',
    pieceRed: '#FF6B6B',
    pieceBlack: '#4ECDC4',
    grid: 'rgba(255,255,255,0.2)',
    highlight: '#3498DB',
    selection: '#F39C12',
    text: '#FFFFFF',
    textMuted: 'rgba(255,255,255,0.6)',
  },
  materials: {
    board: 'glass',
    pieceRed: 'crystal-red',
    pieceBlack: 'crystal-cyan',
    highlight: 'neon-blue',
    grid: 'glass-grid',
  },
  lighting: {
    ambient: 0.6,
    directional: 1.2,
    point: 0.8,
    color: 0xFFFFFF,
  },
  ui: {
    panelBg: 'rgba(26, 26, 46, 0.85)',
    panelBorder: 'rgba(255, 255, 255, 0.1)',
    buttonBg: 'rgba(255, 255, 255, 0.1)',
    buttonHover: 'rgba(255, 255, 255, 0.2)',
    buttonActive: 'rgba(52, 152, 219, 0.4)',
    fontFamily: '"Inter", sans-serif',
    borderRadius: '12px',
    shadow: '0 8px 32px rgba(0, 0, 0, 0.4)',
  },
  animation: {
    pieceMove: 250,
    capture: 400,
    uiTransition: 200,
    hover: 120,
    stagger: 60,
  },
};

export const themes: Record<string, Theme> = {
  qinhan: qinhanTheme,
  tangsong: tangsongTheme,
  mingqing: mingqingTheme,
  modern: modernTheme,
};

export const defaultTheme = mingqingTheme;

// 材质生成器
export class MaterialGenerator {
  static createBronzeMaterial(textureLoader: THREE.TextureLoader): THREE.MeshStandardMaterial {
    const colorMap = textureLoader.load('/textures/bronze_texture.png');
    return new THREE.MeshStandardMaterial({
      color: 0x8B7355,
      metalness: 0.85,
      roughness: 0.35,
      envMapIntensity: 1.0,
      map: colorMap,
    });
  }

  static createJadeMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0x2E8B57,
      metalness: 0.1,
      roughness: 0.15,
      transmission: 0.3,
      thickness: 0.5,
      clearcoat: 0.8,
      clearcoatRoughness: 0.1,
    });
  }

  static createRosewoodMaterial(textureLoader: THREE.TextureLoader): THREE.MeshStandardMaterial {
    const colorMap = textureLoader.load('/textures/rosewood_texture.png');
    return new THREE.MeshStandardMaterial({
      color: 0x8B4513,
      metalness: 0.05,
      roughness: 0.75,
      map: colorMap,
    });
  }

  static createGlassMaterial(): THREE.MeshPhysicalMaterial {
    return new THREE.MeshPhysicalMaterial({
      color: 0xFFFFFF,
      metalness: 0,
      roughness: 0.05,
      transmission: 0.95,
      thickness: 0.3,
      ior: 1.5,
      clearcoat: 1.0,
    });
  }

  static createGoldMaterial(): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: 0xFFD700,
      metalness: 1.0,
      roughness: 0.15,
      envMapIntensity: 1.2,
    });
  }
}

// 动画配置
export const animationConfig = {
  pieceMove: {
    duration: 0.3,
    ease: [0.4, 0, 0.2, 1],
  },
  capture: {
    particleCount: 20,
    duration: 0.5,
  },
  ui: {
    fast: 0.15,
    normal: 0.3,
    slow: 0.5,
    stagger: 0.08,
  },
};
"}

