      case 'bronze':
        return MaterialGenerator.createBronzeMaterial(loader);
      case 'jade':
        return MaterialGenerator.createJadeMaterial();
      case 'rosewood':
        return MaterialGenerator.createRosewoodMaterial(loader);
      case 'glass':
        return MaterialGenerator.createGlassMaterial();
      default:
        return new THREE.MeshStandardMaterial({
          color: isRed ? theme.colors.pieceRed : theme.colors.pieceBlack,
          metalness: 0.3,
          roughness: 0.4,
        });
    }
  }, [isRed, theme]);

  // 文字材质
  const textMaterial = useMemo(() => {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 256;
    const ctx = canvas.getContext('2d')!;

    // 背景圆
    ctx.beginPath();
    ctx.arc(128, 128, 120, 0, Math.PI * 2);
    ctx.fillStyle = isRed ? theme.colors.pieceRed : theme.colors.pieceBlack;
    ctx.fill();

    // 边框
    ctx.strokeStyle = isRed ? '#FFD700' : '#C0C0C0';
    ctx.lineWidth = 4;
    ctx.stroke();

    // 文字
    ctx.font = 'bold 120px "Noto Serif SC", serif';
    ctx.fillStyle = isRed ? '#FFD700' : '#C0C0C0';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(type, 128, 128);

    const texture = new THREE.CanvasTexture(canvas);
    return new THREE.MeshBasicMaterial({ map: texture });
  }, [type, isRed, theme]);

  // 选中/高亮效果
  const selectionRing = useMemo(() => {
    if (!isSelected && !isHighlighted) return null;

    const color = isSelected ? theme.colors.selection : theme.colors.highlight;
    return new THREE.MeshBasicMaterial({
      color: color,
      transparent: true,
      opacity: 0.5,
    });
  }, [isSelected, isHighlighted, theme]);

  // 动画
  useFrame((state) => {
    if (meshRef.current) {
      const time = state.clock.getElapsedTime();

      // 选中时浮动效果
      if (isSelected) {
        meshRef.current.position.y = position[1] + Math.sin(time * 3) * 0.05 + 0.1;
      } else if (hovered) {
        meshRef.current.position.y = position[1] + 0.05;
      } else {
        meshRef.current.position.y = position[1];
      }

      // 悬停缩放
      const targetScale = hovered ? 1.1 : 1;
      meshRef.current.scale.lerp(new THREE.Vector3(targetScale, targetScale, targetScale), 0.1);
    }
  });

  return (
    <group 
      ref={meshRef}
      position={position}
      onClick={onClick}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
    >
      {/* 棋子底座 */}
      <mesh castShadow receiveShadow>
        <cylinderGeometry args={[0.35, 0.4, 0.15, 32]} />
        <primitive object={pieceMaterial} attach="material" />
      </mesh>

      {/* 棋子顶部文字 */}
      <mesh position={[0, 0.08, 0]} rotation={[-Math.PI/2, 0, 0]}>
        <circleGeometry args={[0.3, 32]} />
        <primitive object={textMaterial} attach="material" />
      </mesh>

      {/* 选中/高亮环 */}
      {(isSelected || isHighlighted) && selectionRing && (
        <mesh position={[0, -0.05, 0]}>
          <ringGeometry args={[0.45, 0.5, 32]} />
          <primitive object={selectionRing} attach="material" />
        </mesh>
      )}
    </group>
  );
}

// ============================================
// 3D组件: 光照系统
// ============================================

function Lighting({ theme }: { theme: Theme }) {
  return (
    <>
      {/* 环境光 */}
      <ambientLight intensity={theme.lighting.ambient} color={theme.lighting.color} />

      {/* 主光源 */}
      <directionalLight
        position={[10, 20, 10]}
        intensity={theme.lighting.directional}
        color={theme.lighting.color}
        castShadow
        shadow-mapSize={[2048, 2048]}
        shadow-camera-near={0.5}
        shadow-camera-far={50}
        shadow-camera-left={-10}
        shadow-camera-right={10}
        shadow-camera-top={10}
        shadow-camera-bottom={-10}
      />

      {/* 补光 */}
      <pointLight
        position={[-10, 10, -10]}
        intensity={theme.lighting.point}
        color={theme.lighting.color}
      />

      {/* 轮廓光 */}
      <spotLight
        position={[0, 15, 0]}
        angle={Math.PI / 4}
        penumbra={0.5}
        intensity={0.5}
        color={theme.colors.highlight}
      />
    </>
  );
}

// ============================================
// 主组件: ChessBoard3D
// ============================================

interface ChessBoard3DProps {
  themeId?: string;
  pieces?: Array<{
    id: string;
    type: string;
    isRed: boolean;
    position: [number, number, number];
  }>;
  selectedPiece?: string | null;
  highlightedPositions?: Array<[number, number]>;
  onPieceClick?: (id: string) => void;
}

export function ChessBoard3D({
  themeId = 'mingqing',
  pieces = [],
  selectedPiece = null,
  highlightedPositions = [],
  onPieceClick,
}: ChessBoard3DProps) {
  const theme = themes[themeId] || defaultTheme;
  const controlsRef = useRef<any>(null);

  // 高亮位置映射
  const highlightSet = useMemo(() => {
    const set = new Set<string>();
    highlightedPositions.forEach(pos => {
      set.add(`${pos[0]},${pos[1]}`);
    });
    return set;
  }, [highlightedPositions]);

  return (
    <div 
      className="w-full h-full"
      style={{ background: theme.colors.background }}
    >
      <Canvas
        shadows
        camera={{ position: [0, 12, 8], fov: 45 }}
        gl={{ antialias: true, alpha: true }}
      >
        <color attach="background" args={[theme.colors.background]} />

        {/* 光照 */}
        <Lighting theme={theme} />

        {/* 环境反射 */}
        <Environment preset="studio" />

        {/* 棋盘 */}
        <Board theme={theme} />

        {/* 棋子 */}
        {pieces.map((piece) => (
          <Piece
            key={piece.id}
            position={piece.position}
            type={piece.type}
            isRed={piece.isRed}
            isSelected={selectedPiece === piece.id}
            isHighlighted={highlightSet.has(`${piece.position[0]},${piece.position[2]}`)}
            theme={theme}
            onClick={() => onPieceClick?.(piece.id)}
          />
        ))}

        {/* 阴影 */}
        <ContactShadows
          position={[0, -0.1, 0]}
          opacity={0.4}
          scale={20}
          blur={2}
          far={10}
        />

        {/* 控制器 */}
        <OrbitControls
          ref={controlsRef}
          enablePan={true}
          enableZoom={true}
          enableRotate={true}
          minDistance={5}
          maxDistance={20}
          minPolarAngle={0}
          maxPolarAngle={Math.PI / 2.2}
          target={[0, 0, 0]}
        />
      </Canvas>
    </div>
  );
}

// ============================================
// UI组件: 主题选择器
// ============================================

interface ThemeSelectorProps {
  currentTheme: string;
  onThemeChange: (themeId: string) => void;
}

export function ThemeSelector({ currentTheme, onThemeChange }: ThemeSelectorProps) {
  return (
    <div className="flex gap-2 p-4">
      {Object.values(themes).map((theme) => (
        <motion.button
          key={theme.id}
          onClick={() => onThemeChange(theme.id)}
          className="px-4 py-2 rounded-lg font-medium transition-all"
          style={{
            background: currentTheme === theme.id ? theme.colors.accent : theme.colors.surface,
            color: theme.colors.text,
            border: `1px solid ${theme.colors.panelBorder}`,
            fontFamily: theme.ui.fontFamily,
          }}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {theme.name}
        </motion.button>
      ))}
    </div>
  );
}

export default ChessBoard3D;
