/**
 * GameUI - 升级版本 v2.0
 * 应用高水平美学设计系统
 * 
 * 设计原则：
 * - 70-20-10 配色规则
 * - 8pt 网格系统
 * - 游戏UI设计模式 (game-ui-design)
 */

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Theme, themes, defaultTheme } from '../themes';

// ============================================
// 类型定义
// ============================================

interface GameUIProps {
  themeId?: string;
  onThemeChange?: (themeId: string) => void;
  currentPlayer?: 'red' | 'black';
  moveHistory?: string[];
  capturedPieces?: { red: string[]; black: string[] };
  timer?: { red: number; black: number };
  onUndo?: () => void;
  onReset?: () => void;
  onSettings?: () => void;
}

interface PanelProps {
  theme: Theme;
  children: React.ReactNode;
  title?: string;
  className?: string;
}

// ============================================
// 基础组件: 面板
// ============================================

function Panel({ theme, children, title, className = '' }: PanelProps) {
  return (
    <motion.div
      className={`rounded-lg overflow-hidden ${className}`}
      style={{
        background: theme.ui.panelBg,
        border: `1px solid ${theme.ui.panelBorder}`,
        borderRadius: theme.ui.borderRadius,
        boxShadow: theme.ui.shadow,
      }}
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: theme.animation.uiTransition / 1000 }}
    >
      {title && (
        <div 
          className="px-4 py-3 border-b"
          style={{ borderColor: theme.ui.panelBorder }}
        >
          <h3 
            className="text-lg font-semibold"
            style={{ 
              color: theme.colors.text,
              fontFamily: theme.ui.fontFamily,
            }}
          >
            {title}
          </h3>
        </div>
      )}
      <div className="p-4">
        {children}
      </div>
    </motion.div>
  );
}

// ============================================
// 基础组件: 按钮
// ============================================

interface ButtonProps {
  theme: Theme;
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  disabled?: boolean;
  icon?: React.ReactNode;
}

function Button({ 
  theme, 
  children, 
  onClick, 
  variant = 'secondary',
  size = 'md',
  disabled = false,
  icon,
}: ButtonProps) {
  const sizeClasses = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-4 py-2',
    lg: 'px-6 py-3 text-lg',
  };

  const getBackground = () => {
    if (disabled) return 'rgba(128,128,128,0.2)';
    switch (variant) {
      case 'primary': return theme.colors.accent;
      case 'secondary': return theme.ui.buttonBg;
      case 'ghost': return 'transparent';
      default: return theme.ui.buttonBg;
    }
  };

  return (
    <motion.button
      onClick={onClick}
      disabled={disabled}
      className={`flex items-center justify-center gap-2 font-medium transition-all ${sizeClasses[size]}`}
      style={{
        background: getBackground(),
        color: theme.colors.text,
        borderRadius: theme.ui.borderRadius,
        fontFamily: theme.ui.fontFamily,
        border: variant === 'ghost' ? `1px solid ${theme.ui.panelBorder}` : 'none',
        opacity: disabled ? 0.5 : 1,
        cursor: disabled ? 'not-allowed' : 'pointer',
      }}
      whileHover={!disabled ? { 
        background: variant === 'primary' ? theme.colors.accent : theme.ui.buttonHover,
        scale: 1.02,
      } : {}}
      whileTap={!disabled ? { scale: 0.98 } : {}}
      transition={{ duration: theme.animation.hover / 1000 }}
    >
      {icon && <span>{icon}</span>}
      {children}
    </motion.button>
  );
}

// ============================================
// 组件: 玩家信息面板
// ============================================

interface PlayerInfoProps {
  theme: Theme;
  isRed: boolean;
  isActive: boolean;
  time: number;
  capturedCount: number;
}

function PlayerInfo({ theme, isRed, isActive, time, capturedCount }: PlayerInfoProps) {
  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <motion.div
      className="flex items-center gap-4 p-4 rounded-lg"
      style={{
        background: isActive ? `${theme.colors.accent}20` : theme.colors.surface,
        border: `2px solid ${isActive ? theme.colors.accent : theme.ui.panelBorder}`,
        borderRadius: theme.ui.borderRadius,
      }}
      animate={isActive ? {
        boxShadow: [`0 0 0px ${theme.colors.accent}00`, `0 0 20px ${theme.colors.accent}40`, `0 0 0px ${theme.colors.accent}00`],
      } : {}}
      transition={{ duration: 2, repeat: Infinity }}
    >
      {/* 玩家头像/标识 */}
      <div
        className="w-12 h-12 rounded-full flex items-center justify-center text-2xl font-bold"
        style={{
          background: isRed ? theme.colors.pieceRed : theme.colors.pieceBlack,
          color: '#FFF',
          fontFamily: theme.ui.fontFamily,
        }}
      >
        {isRed ? '红' : '黑'}
      </div>

      {/* 玩家信息 */}
      <div className="flex-1">
        <div 
          className="font-semibold text-lg"
          style={{ 
            color: theme.colors.text,
            fontFamily: theme.ui.fontFamily,
          }}
        >
          {isRed ? '红方' : '黑方'}
          {isActive && (
            <span 
              className="ml-2 text-sm px-2 py-0.5 rounded"
              style={{ 
                background: theme.colors.accent,
                color: '#FFF',
              }}
            >
              当前回合
            </span>
          )}
        </div>
        <div 
          className="text-sm"
          style={{ color: theme.colors.textMuted }}
        >
          用时: {formatTime(time)} | 吃子: {capturedCount}
        </div>
      </div>
    </motion.div>
  );
}

// ============================================
// 组件: 主题选择器
// ============================================

interface ThemeSelectorProps {
  theme: Theme;
  currentThemeId: string;
  onThemeChange: (themeId: string) => void;
}

function ThemeSelectorPanel({ theme, currentThemeId, onThemeChange }: ThemeSelectorProps) {
  return (
    <Panel theme={theme} title="选择主题">
      <div className="grid grid-cols-2 gap-3">
        {Object.values(themes).map((t, index) => (
          <motion.button
            key={t.id}
            onClick={() => onThemeChange(t.id)}
            className="p-3 rounded-lg text-left transition-all"
            style={{
              background: currentThemeId === t.id ? `${t.colors.accent}30` : t.colors.surface,
              border: `2px solid ${currentThemeId === t.id ? t.colors.accent : t.ui.panelBorder}`,
              borderRadius: theme.ui.borderRadius,
            }}
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.05 }}
          >
            <div 
              className="font-semibold mb-1"
              style={{ 
                color: t.colors.text,
                fontFamily: theme.ui.fontFamily,
              }}
            >
              {t.name}
            </div>
            <div 
              className="text-xs"
              style={{ color: t.colors.textMuted }}
            >
              {t.era}
            </div>
            <div 
              className="flex gap-1 mt-2"
            >
              <div 
                className="w-6 h-6 rounded"
                style={{ background: t.colors.primary }}
              />
              <div 
                className="w-6 h-6 rounded"
                style={{ background: t.colors.secondary }}
              />
              <div 
                className="w-6 h-6 rounded"
                style={{ background: t.colors.accent }}
              />
            </div>
          </motion.button>
        ))}
      </div>
    </Panel>
  );
}

// ============================================
// 组件: 吃子记录
// ============================================

interface CapturedPiecesProps {
  theme: Theme;
  capturedPieces: { red: string[]; black: string[] };
}

function CapturedPieces({ theme, capturedPieces }: CapturedPiecesProps) {
  const pieceIcons: Record<string, string> = {
    '将': '帅', '帅': '将',
    '士': '仕', '仕': '士',
    '象': '相', '相': '象',
    '马': '傌', '傌': '马',
    '车': '俥', '俥': '车',
    '炮': '炮',
    '兵': '卒', '卒': '兵',
  };

  return (
    <Panel theme={theme} title="吃子记录">
      <div className="space-y-4">
        {/* 红方吃子 */}
        <div>
          <div 
            className="text-sm font-medium mb-2"
            style={{ color: theme.colors.pieceRed }}
          >
            红方吃掉
          </div>
          <div className="flex flex-wrap gap-1">
            {capturedPieces.red.length === 0 ? (
              <span style={{ color: theme.colors.textMuted }}>无</span>
            ) : (
              capturedPieces.red.map((piece, i) => (
                <motion.span
                  key={i}
                  className="w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold"
                  style={{
                    background: theme.colors.pieceBlack,
                    color: '#C0C0C0',
                    border: '1px solid #666',
                  }}
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ delay: i * 0.05 }}
                >
                  {pieceIcons[piece] || piece}
                </motion.span>
              ))
            )}
          </div>
        </div>

        {/* 黑方吃子 */}
        <div>
          <div 
            className="text-sm font-medium mb-2"
            style={{ color: theme.colors.pieceBlack }}
          >
            黑方吃掉
          </div>
          <div className="flex flex-wrap gap-1">
            {capturedPieces.black.length === 0 ? (
              <span style={{ color: theme.colors.textMuted }}>无</span>
            ) : (
              capturedPieces.black.map((piece, i) => (
                <motion.span
                  key={i}
                  className="w-8 h-8 rounded-full flex items-center justify-center text-sm font-bold"
                  style={{
                    background: theme.colors.pieceRed,
                    color: '#FFD700',
                    border: '1px solid #B87333',
                  }}
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ delay: i * 0.05 }}
                >
                  {pieceIcons[piece] || piece}
                </motion.span>
              ))
            )}
          </div>
        </div>
      </div>
    </Panel>
  );
}

// ============================================
// 组件: 走棋记录
// ============================================

interface MoveHistoryProps {
  theme: Theme;
  moves: string[];
}

function MoveHistory({ theme, moves }: MoveHistoryProps) {
  return (
    <Panel theme={theme} title="走棋记录">
      <div 
        className="h-48 overflow-y-auto space-y-1 pr-2"
        style={{
          scrollbarWidth: 'thin',
          scrollbarColor: `${theme.ui.panelBorder} transparent`,
        }}
      >
        {moves.length === 0 ? (
          <div 
            className="text-center py-8"
            style={{ color: theme.colors.textMuted }}
          >
            暂无走棋记录
          </div>
        ) : (
          moves.map((move, index) => (
            <motion.div
              key={index}
              className="flex items-center gap-2 p-2 rounded"
              style={{
                background: index % 2 === 0 ? 'rgba(255,255,255,0.05)' : 'transparent',
              }}
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.02 }}
            >
              <span 
                className="text-xs w-8"
                style={{ color: theme.colors.textMuted }}
              >
                {index + 1}.
              </span>
              <span style={{ color: theme.colors.text }}>
                {move}
              </span>
            </motion.div>
          ))
        )}
      </div>
    </Panel>
  );
}

// ============================================
// 主组件: GameUI
// ============================================

export function GameUI({
  themeId = 'mingqing',
  onThemeChange,
  currentPlayer = 'red',
  moveHistory = [],
  capturedPieces = { red: [], black: [] },
  timer = { red: 0, black: 0 },
  onUndo,
  onReset,
  onSettings,
}: GameUIProps) {
  const theme = themes[themeId] || defaultTheme;
  const [showSettings, setShowSettings] = useState(false);

  return (
    <div 
      className="w-full h-full flex flex-col gap-4 p-4"
      style={{ 
        background: theme.colors.background,
        fontFamily: theme.ui.fontFamily,
      }}
    >
      {/* 顶部: 玩家信息 */}
      <div className="grid grid-cols-2 gap-4">
        <PlayerInfo
          theme={theme}
          isRed={true}
          isActive={currentPlayer === 'red'}
          time={timer.red}
          capturedCount={capturedPieces.red.length}
        />
        <PlayerInfo
          theme={theme}
          isRed={false}
          isActive={currentPlayer === 'black'}
          time={timer.black}
          capturedCount={capturedPieces.black.length}
        />
      </div>

      {/* 中部: 游戏控制 */}
      <div className="flex gap-2">
        <Button theme={theme} onClick={onUndo} variant="secondary" icon="↩">
          悔棋
        </Button>
        <Button theme={theme} onClick={onReset} variant="secondary" icon="⟲">
          重新开始
        </Button>
        <Button 
          theme={theme} 
          onClick={() => setShowSettings(!showSettings)} 
          variant="primary"
          icon="⚙"
        >
          主题设置
        </Button>
      </div>

      {/* 主题选择器 */}
      <AnimatePresence>
        {showSettings && onThemeChange && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: theme.animation.uiTransition / 1000 }}
          >
            <ThemeSelectorPanel
              theme={theme}
              currentThemeId={themeId}
              onThemeChange={(id) => {
                onThemeChange(id);
                setShowSettings(false);
              }}
            />
          </motion.div>
        )}
      </AnimatePresence>

      {/* 吃子记录 */}
      <CapturedPieces theme={theme} capturedPieces={capturedPieces} />

      {/* 走棋记录 */}
      <MoveHistory theme={theme} moves={moveHistory} />
    </div>
  );
}

export default GameUI;

