/**
 * 3D中国象棋 - 高水平美学升级版 v2.0
 * 完整演示应用
 */

import React, { useState, useCallback } from 'react';
import { ChessBoard3D, ThemeSelector } from './components/ChessBoard3D';
import { GameUI } from './components/GameUI';
import { themes, defaultTheme } from './themes';

// 示例棋子数据
const initialPieces = [
  // 红方
  { id: 'r1', type: '車', isRed: true, position: [-4, 0.2, -4.5] as [number, number, number] },
  { id: 'r2', type: '馬', isRed: true, position: [-3, 0.2, -4.5] as [number, number, number] },
  { id: 'r3', type: '相', isRed: true, position: [-2, 0.2, -4.5] as [number, number, number] },
  { id: 'r4', type: '仕', isRed: true, position: [-1, 0.2, -4.5] as [number, number, number] },
  { id: 'r5', type: '帥', isRed: true, position: [0, 0.2, -4.5] as [number, number, number] },
  { id: 'r6', type: '仕', isRed: true, position: [1, 0.2, -4.5] as [number, number, number] },
  { id: 'r7', type: '相', isRed: true, position: [2, 0.2, -4.5] as [number, number, number] },
  { id: 'r8', type: '馬', isRed: true, position: [3, 0.2, -4.5] as [number, number, number] },
  { id: 'r9', type: '車', isRed: true, position: [4, 0.2, -4.5] as [number, number, number] },
  { id: 'r10', type: '炮', isRed: true, position: [-3, 0.2, -2.5] as [number, number, number] },
  { id: 'r11', type: '炮', isRed: true, position: [3, 0.2, -2.5] as [number, number, number] },
  { id: 'r12', type: '兵', isRed: true, position: [-4, 0.2, -1.5] as [number, number, number] },
  { id: 'r13', type: '兵', isRed: true, position: [-2, 0.2, -1.5] as [number, number, number] },
  { id: 'r14', type: '兵', isRed: true, position: [0, 0.2, -1.5] as [number, number, number] },
  { id: 'r15', type: '兵', isRed: true, position: [2, 0.2, -1.5] as [number, number, number] },
  { id: 'r16', type: '兵', isRed: true, position: [4, 0.2, -1.5] as [number, number, number] },

  // 黑方
  { id: 'b1', type: '車', isRed: false, position: [-4, 0.2, 4.5] as [number, number, number] },
  { id: 'b2', type: '馬', isRed: false, position: [-3, 0.2, 4.5] as [number, number, number] },
  { id: 'b3', type: '象', isRed: false, position: [-2, 0.2, 4.5] as [number, number, number] },
  { id: 'b4', type: '士', isRed: false, position: [-1, 0.2, 4.5] as [number, number, number] },
  { id: 'b5', type: '將', isRed: false, position: [0, 0.2, 4.5] as [number, number, number] },
  { id: 'b6', type: '士', isRed: false, position: [1, 0.2, 4.5] as [number, number, number] },
  { id: 'b7', type: '象', isRed: false, position: [2, 0.2, 4.5] as [number, number, number] },
  { id: 'b8', type: '馬', isRed: false, position: [3, 0.2, 4.5] as [number, number, number] },
  { id: 'b9', type: '車', isRed: false, position: [4, 0.2, 4.5] as [number, number, number] },
  { id: 'b10', type: '炮', isRed: false, position: [-3, 0.2, 2.5] as [number, number, number] },
  { id: 'b11', type: '炮', isRed: false, position: [3, 0.2, 2.5] as [number, number, number] },
  { id: 'b12', type: '卒', isRed: false, position: [-4, 0.2, 1.5] as [number, number, number] },
  { id: 'b13', type: '卒', isRed: false, position: [-2, 0.2, 1.5] as [number, number, number] },
  { id: 'b14', type: '卒', isRed: false, position: [0, 0.2, 1.5] as [number, number, number] },
  { id: 'b15', type: '卒', isRed: false, position: [2, 0.2, 1.5] as [number, number, number] },
  { id: 'b16', type: '卒', isRed: false, position: [4, 0.2, 1.5] as [number, number, number] },
];

// 示例走棋记录
const sampleMoves = [
  '1. 炮二平五',
  '1. ... 馬8进7',
  '2. 馬二进三',
  '2. ... 車9平8',
  '3. 車一平二',
  '3. ... 馬2进3',
  '4. 兵七进一',
  '4. ... 卒7进1',
  '5. 馬八进七',
  '5. ... 炮2进4',
];

// 示例吃子记录
const sampleCaptured = {
  red: ['卒', '馬'],
  black: ['兵'],
};

function App() {
  const [currentTheme, setCurrentTheme] = useState('mingqing');
  const [selectedPiece, setSelectedPiece] = useState<string | null>(null);
  const [pieces, setPieces] = useState(initialPieces);
  const [currentPlayer, setCurrentPlayer] = useState<'red' | 'black'>('red');
  const [moveHistory, setMoveHistory] = useState<string[]>(sampleMoves);
  const [capturedPieces, setCapturedPieces] = useState(sampleCaptured);
  const [timer, setTimer] = useState({ red: 180, black: 180 });

  const theme = themes[currentTheme] || defaultTheme;

  const handlePieceClick = useCallback((id: string) => {
    setSelectedPiece(prev => prev === id ? null : id);
  }, []);

  const handleThemeChange = useCallback((themeId: string) => {
    setCurrentTheme(themeId);
  }, []);

  const handleUndo = useCallback(() => {
    console.log('悔棋');
  }, []);

  const handleReset = useCallback(() => {
    setPieces(initialPieces);
    setSelectedPiece(null);
    setCurrentPlayer('red');
    setMoveHistory([]);
    setCapturedPieces({ red: [], black: [] });
    setTimer({ red: 180, black: 180 });
  }, []);

  return (
    <div 
      className="w-screen h-screen flex overflow-hidden"
      style={{ background: theme.colors.background }}
    >
      {/* 左侧: 3D棋盘 */}
      <div className="flex-1 h-full relative">
        <ChessBoard3D
          themeId={currentTheme}
          pieces={pieces}
          selectedPiece={selectedPiece}
          highlightedPositions={[[0, 0], [1, 0], [2, 0]]}
          onPieceClick={handlePieceClick}
        />

        {/* 主题选择器浮层 */}
        <div 
          className="absolute top-4 left-4 z-10"
          style={{
            background: theme.ui.panelBg,
            borderRadius: theme.ui.borderRadius,
            border: `1px solid ${theme.ui.panelBorder}`,
            boxShadow: theme.ui.shadow,
          }}
        >
          <ThemeSelector
            currentTheme={currentTheme}
            onThemeChange={handleThemeChange}
          />
        </div>

        {/* 版本信息 */}
        <div 
          className="absolute bottom-4 left-4 px-3 py-2 rounded text-sm"
          style={{
            background: theme.ui.panelBg,
            color: theme.colors.textMuted,
            border: `1px solid ${theme.ui.panelBorder}`,
          }}
        >
          3D中国象棋 v2.0 | {theme.name}
        </div>
      </div>

      {/* 右侧: 游戏UI */}
      <div className="w-80 h-full border-l" style={{ borderColor: theme.ui.panelBorder }}>
        <GameUI
          themeId={currentTheme}
          onThemeChange={handleThemeChange}
          currentPlayer={currentPlayer}
          moveHistory={moveHistory}
          capturedPieces={capturedPieces}
          timer={timer}
          onUndo={handleUndo}
          onReset={handleReset}
        />
      </div>
    </div>
  );
}

export default App;

