  background: rgba(255, 255, 255, 0.2);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3);
}

/* Canvas 样式 */
canvas {
  display: block;
}

/* 选中文字样式 */
::selection {
  background: rgba(255, 215, 0, 0.3);
  color: inherit;
}

